import unittest
from example import discounted_total

class ExampleTests(unittest.TestCase):
    def test_case_0(self):
        self.assertEqual(discounted_total([100, 50], 0.2), 120)
    def test_case_1(self):
        self.assertEqual(discounted_total([12], 0), 12)
    def test_case_2(self):
        self.assertEqual(discounted_total([], 0.5), 0)

